// ============================================================================
// Nó 2: Montar Kit Social & Preview (n8n Code Node)
// ============================================================================
const item = $input.first().json.body || $input.first().json || {};

const slug = (item.slug || 'artigo-tecnico').trim();
const articleUrl = item.article_url || `https://marcos-data-engineer.github.io/blog/posts/${slug}/`;
const coverPath = item.cover_container_path || `/data/blog/assets/img/posts/${slug}/cover.jpg`;
const linkedinMain = item.linkedin_main || 'Post LinkedIn corporativo';
const linkedinComment = item.linkedin_comment || `Artigo completo: ${articleUrl}`;
const xMain = item.x_main || 'Tweet principal';
const xReply = item.x_reply || `Leia em: ${articleUrl}`;

// Callback data curto para Telegram (Limite estrito de 64 bytes)
const callbackPublish = `pub:${slug}`.slice(0, 64);
const callbackSkip = `skip:${slug}`.slice(0, 64);

// Formatação do Preview para envio via Telegram Bot API
const telegramCaption = [
  `📢 *APROVAÇÃO 1-CLIQUE: KIT SOCIAL DISPONÍVEL*`,
  ``,
  `📌 *Artigo:* [${slug}](${articleUrl})`,
  ``,
  `💼 *PRÉVIA LINKEDIN:*`,
  `${linkedinMain.slice(0, 350)}...`,
  ``,
  `💬 *1º COMENTÁRIO:*`,
  `${linkedinComment.slice(0, 180)}...`,
  ``,
  `⚡ *PRÉVIA X (TWITTER):*`,
  `${xMain.slice(0, 140)}...`,
  ``,
  `Escolha abaixo para disparar as publicações oficiais:`
].join('\n');

const inlineKeyboard = {
  inline_keyboard: [
    [
      { text: "🚀 Aprovar e Publicar Agora", callback_data: callbackPublish },
      { text: "❌ Descartar", callback_data: callbackSkip }
    ]
  ]
};

return [{
  json: {
    slug,
    article_url: articleUrl,
    cover_container_path: coverPath,
    linkedin_main: linkedinMain,
    linkedin_comment: linkedinComment,
    x_main: xMain,
    x_reply: xReply,
    telegram_caption: telegramCaption.slice(0, 1020),
    telegram_reply_markup: inlineKeyboard,
    callback_publish: callbackPublish,
    callback_skip: callbackSkip
  }
}];

