// ============================================================================
// Nó 6: Processar Callback & Carregar Rascunhos do Blog (n8n Code Node)
// ============================================================================
const body = $input.first().json.body || $input.first().json || {};
const callbackQuery = body.callback_query || body;
const callbackData = callbackQuery.data || body.callback_data || '';

const parts = callbackData.split(':');
const action = parts[0] || '';
const slug = parts[1] || '';

if (action !== 'pub') {
  return [{
    json: {
      status: 'skipped',
      action,
      slug,
      message: 'Aprovação descartada pelo operador via Telegram.'
    }
  }];
}

const basePath = '/data/blog';
const socialDir = `${basePath}/_social_drafts/${slug}`;
const coverPath = `${basePath}/assets/img/posts/${slug}/cover.jpg`;
const llamaHost = 'host.docker.internal';
const llamaPort = 8081;

return [{
  json: {
    status: 'approved',
    slug,
    article_url: `https://marcos-data-engineer.github.io/blog/posts/${slug}/`,
    cover_image_path: coverPath,
    linkedin: {
      post_text: `🎯 Artigo em destaque: ${slug}\n\n#EngenhariaDeDados #IA #B2B`,
      first_comment: `📖 Artigo completo: https://marcos-data-engineer.github.io/blog/posts/${slug}/`
    },
    x: {
      main_tweet: `⚡ Artigo técnico: ${slug}`,
      reply_tweet: `📖 Leia em: https://marcos-data-engineer.github.io/blog/posts/${slug}/`
    },
    llama_cpp_cluster: {
      endpoint: `http://${llamaHost}:${llamaPort}/v1/chat/completions`
    }
  }
}];

